def minOperationsToFlip(expression):
    # For each subexpression keep (c0, c1): min ops to force it to evaluate to 0 / to 1.
    # No operator precedence and left-to-right evaluation, so fold a value into the
    # pending operator as soon as it is complete. One of the final pair is 0 (the
    # current value); the other is the cost to flip it.
    def combine(L, R, op):
        l0, l1 = L
        r0, r1 = R
        and0 = min(l0 + r0, l0 + r1, l1 + r0)
        and1 = l1 + r1
        or0 = l0 + r0
        or1 = min(l1 + r1, l1 + r0, l0 + r1)
        c0 = min(and0 + (0 if op == '&' else 1), or0 + (0 if op == '|' else 1))
        c1 = min(and1 + (0 if op == '&' else 1), or1 + (0 if op == '|' else 1))
        return (c0, c1)

    st = []

    def push_value(v):
        if st and st[-1] in ('&', '|'):
            op = st.pop()
            left = st.pop()
            v = combine(left, v, op)
        st.append(v)

    for ch in expression:
        if ch == '0':
            push_value((0, 1))
        elif ch == '1':
            push_value((1, 0))
        elif ch == '&' or ch == '|':
            st.append(ch)
        elif ch == '(':
            st.append('(')
        elif ch == ')':
            v = st.pop()
            st.pop()  # discard '('
            push_value(v)

    c0, c1 = st.pop()
    return max(c0, c1)

